/// Icons (port of android res/drawable/ic_*.xml): vector SVG imagesets in Assets.xcassets,
/// generated by ios/tools/vector_to_svg.py. 24x24 viewport, 1.9 stroke, template rendering
/// (tinted by foregroundStyle), except `myLocation` which keeps its own blue colors.
///
/// Surface:
/// - `enum AppIcon: String, CaseIterable` (`back, bag, bell, ... user`), `var assetName: String` ("ic_back"),
///   `var image: Image`
/// - `struct IconImage: View` - `IconImage(_ icon: AppIcon, size: CGFloat = 24, tint: Color? = nil)`
///   (Android `Icon(painterResource(..), tint, Modifier.size(..))`; nil tint = current foreground style)

import SwiftUI

/// Ilovadagi belgilar. Nomlari Android'dagi `ic_...` fayllaridan.
enum AppIcon: String, CaseIterable {
    case back
    case bag
    case bell
    case bike
    case bolt
    case cash
    case check
    case chef
    case chevron
    case clock
    case close
    case dish
    case gps
    case home
    case info
    case message
    case minus
    case myLocation
    case phone
    case pin
    case plus
    case receipt
    case refresh
    case `repeat`
    case search
    case send
    case tag
    case user

    /// Asset katalogidagi nomi: `ic_back`, `ic_my_location`, ...
    var assetName: String {
        switch self {
        case .myLocation:
            return "ic_my_location"
        default:
            return "ic_" + rawValue
        }
    }

    /// Belgi rasmi. `myLocation` o'z ranglarida, qolganlari `foregroundStyle` rangida chiziladi.
    var image: Image {
        switch self {
        case .myLocation:
            return Image(assetName).renderingMode(.original)
        default:
            return Image(assetName).renderingMode(.template)
        }
    }
}

/// Belgi: kvadrat o'lchamda, berilgan rangda. Ekran o'quvchisi uchun yashirin (yozuv tugmaning o'zida).
struct IconImage: View {
    let icon: AppIcon
    var size: CGFloat = 24
    var tint: Color? = nil

    init(_ icon: AppIcon, size: CGFloat = 24, tint: Color? = nil) {
        self.icon = icon
        self.size = size
        self.tint = tint
    }

    var body: some View {
        let base = icon.image
            .resizable()
            .scaledToFit()
            .frame(width: size, height: size)
            .accessibilityHidden(true)
        if let tint {
            base.foregroundStyle(tint)
        } else {
            base
        }
    }
}
